-- Restoration SQL Script for 11 Invoices
-- Target Invoices: 278456, 278477, 278510, 278512, 278513, 278514, 278535, 278536, 278537, 278538, 278624

DELETE FROM `invoice_items` WHERE `invoice_id` IN (278456, 278477, 278510, 278512, 278513, 278514, 278535, 278536, 278537, 278538, 278624);


-- Re-sync total_amount on invoices table to match sum of invoice items
UPDATE invoices i SET total_amount = (SELECT SUM(total) FROM invoice_items ii WHERE ii.invoice_id = i.id) WHERE i.id IN (278456, 278477, 278510, 278512, 278513, 278514, 278535, 278536, 278537, 278538, 278624);

-- Re-sync delivery_picking_items for associated deliveries
DELETE FROM delivery_picking_items WHERE delivery_id IN (SELECT DISTINCT id FROM deliveries WHERE rep_route_id IN (SELECT rep_route_id FROM invoices WHERE id IN (278456, 278477, 278510, 278512, 278513, 278514, 278535, 278536, 278537, 278538, 278624)));

SELECT d.id, ii.description, ii.item_id, ii.variation_option_id, SUM(ii.quantity) as required_qty, SUM(ii.loaded_quantity) as loaded_qty
FROM deliveries d
JOIN invoices i ON i.rep_route_id = d.rep_route_id
JOIN invoice_items ii ON ii.invoice_id = i.id
WHERE i.id IN (278456, 278477, 278510, 278512, 278513, 278514, 278535, 278536, 278537, 278538, 278624) AND i.status != 'Voided'
GROUP BY d.id, ii.description, ii.item_id, ii.variation_option_id;
